window.CAR_BENCH_RESULTS={"schemaVersion":"1.0","announcementStatus":"final","generatedAt":"2026-08-03T19:42:32.101577+00:00","evaluation":{"tasks":30,"trialsPerTask":3,"trialsPerSubmission":90,"costNote":"Reported-token estimate with a 75% prompt-cache assumption."},"tracks":{"track_1":{"label":"Track 1 · Open Track","shortLabel":"Track 1"},"track_2":{"label":"Track 2 · Cerebras Fast-Reasoning","shortLabel":"Track 2"}},"teams":[{"key":"track_1__team-35","track":"track_1","teamId":"team-35","teamName":"Darwin Agent","mainLlm":"GPT-5.6 Sol","report":"reports/track_1/team-35.pdf","award":{"award":"Rank Award","award_order":1,"innovation":"TRACE evolves a modular skill bank by contrasting successful and failed tool-use trajectories, then retrieves operation-level guidance at inference time.","rationale":"Darwin Agent led Track 1 with 70.00% Pass³. Its skill-evolution framework combined the strongest hidden-set consistency with a substantive, transferable approach to improving agent behavior across model backbones."},"summary":{"punchline":"TRACE contrasts successful and failed skill-using trajectories to iteratively rewrite a modular, operation-level skill bank that transfers across model backbones.","body":"Darwin Agent's TRACE separates an Actor, which selects and executes markdown skills per turn, from a Curator that evolves those skills offline. Initialization distills trajectories from task-level patterns through task-type aggregation into operation-level competencies, then decomposes broad skills for precise retrieval. After each evaluation round, trajectories are clustered by invoked skill, reconstructed with runtime-visible versus privileged evidence separated, and contrasted to refine existing skills or discover missing ones under a de-hardcoding constraint. The report claims GPT-5.5 Pass3 rises from 59.9% to 94.5% and GLM-5.2 from 62.8% to 84.8%, with the same bank transferring across backbones. However, the bank is broadened using both training and test splits and results are reported on their combination, so they are not a held-out generalization estimate; LLM self-selection may also scale poorly as the bank grows."},"metrics":{"pass3":0.7,"passAt3":0.833333333333,"pass1":0.7,"categories":{"base":{"pass3":0.5,"pass_at_3":0.7,"pass1":0.5},"hallucination":{"pass3":1.0,"pass_at_3":1.0,"pass1":1.0},"disambiguation":{"pass3":0.6,"pass_at_3":0.8,"pass1":0.6}},"successfulTrials":69,"successfulTrialsTotal":90,"successConsistency":0.88,"taskLatencyMeanMs":32437.694444444445,"taskLatencyMedianMs":25873.3,"taskLatencyP95Ms":70932.9,"turnLatencyMedianMs":3828.3,"meanTokensPerTrial":141684.26666666666,"estimatedCostPerTrialUsd":0.274490583333,"rank":{"start":1,"end":1,"total":21,"label":"1./21"}}},{"key":"track_1__team-28","track":"track_1","teamId":"team-28","teamName":"Thylinao","mainLlm":"Gemini 3.5 Flash","report":"reports/track_1/team-28.pdf","award":null,"summary":{"punchline":"A live-schema guard retries invalid calls, while gated admission rejects changes that cannot survive full-split regression testing under a faithful simulator.","body":"Thylinao extends the starter LiteLLM agent with temperature-zero decoding, a per-turn validator against the evaluator's live tool schema, Gemini 3.5 Flash at high reasoning, and a general behavior skill for confirmation, units, minimal action, and honest capability limits. Invalid tool names, arguments, or missing required parameters trigger an in-turn retry; repeated violations are stripped. Candidate rules pass a probe, neighboring-task sweep, regression gate, and full-split rerun before shipping, with configuration baked into and verified inside the container. The report measures 80.2% Pass3 on the full 129-task training split and 78.0% on a preregistered public test read. It identifies the model upgrade as the dominant lever; comparisons to published references are cross-era, individual skill and reasoning contributions are not isolated, and the hidden mix may differ."},"metrics":{"pass3":0.666666666667,"passAt3":0.866666666667,"pass1":0.7,"categories":{"base":{"pass3":0.6,"pass_at_3":0.8,"pass1":0.6},"hallucination":{"pass3":0.8,"pass_at_3":0.9,"pass1":0.8},"disambiguation":{"pass3":0.6,"pass_at_3":0.9,"pass1":0.7}},"successfulTrials":67,"successfulTrialsTotal":90,"successConsistency":0.788461538462,"taskLatencyMeanMs":66771.52584269663,"taskLatencyMedianMs":52854.3,"taskLatencyP95Ms":139764.5,"turnLatencyMedianMs":4376.6,"meanTokensPerTrial":263939.4157303371,"estimatedCostPerTrialUsd":0.24489306236,"rank":{"start":2,"end":2,"total":21,"label":"2./21"}}},{"key":"track_1__team-2","track":"track_1","teamId":"team-2","teamName":"Xzlon","mainLlm":"Gemini 3.5 Flash","report":"reports/track_1/team-2.pdf","award":null,"summary":{"punchline":"Xzlon locks missing-tool checks, ambiguity resolution, and user-specified values in Python before Gemini plans or executes vehicle actions.","body":"Xzlon presents a three-layer A2A agent: deterministic Python guardrails, a Gemini 3.5 Flash planner at temperature 0, and sequential execution that enforces locked parameters. The guardrails validate tool availability, use stored preferences to resolve ambiguous values, and extract explicit numeric values with regex so later plans cannot drift. The report claims all three local smoke tasks passed, yielding 100% Pass1, with a total smoke cost of $0.20 and near-zero model cost for the hallucination case. It did not complete the full 129-task public validation because a Windows uv subprocess issue prevented child processes from inheriting the intended interpreter, so its quantitative evidence is limited to the smoke test rather than a full benchmark run."},"metrics":{"pass3":0.633333333333,"passAt3":0.8,"pass1":0.8,"categories":{"base":{"pass3":0.7,"pass_at_3":0.7,"pass1":0.7},"hallucination":{"pass3":0.6,"pass_at_3":0.8,"pass1":0.8},"disambiguation":{"pass3":0.6,"pass_at_3":0.9,"pass1":0.9}},"successfulTrials":66,"successfulTrialsTotal":90,"successConsistency":0.875,"taskLatencyMeanMs":60235.76555555556,"taskLatencyMedianMs":41004.5,"taskLatencyP95Ms":149519.9,"turnLatencyMedianMs":4705.95,"meanTokensPerTrial":216641.83333333334,"estimatedCostPerTrialUsd":0.183859415417,"rank":{"start":3,"end":3,"total":21,"label":"3./21"}}},{"key":"track_1__team-8","track":"track_1","teamId":"team-8","teamName":"10cars","mainLlm":"Claude Opus 4.6","report":"reports/track_1/team-8.pdf","award":{"award":"Innovation Award","award_order":3,"innovation":"A transcript-derived state ledger and fail-closed pre-flight gate enforce schema, ordering, confirmation, preference, and idempotence requirements.","rationale":"10cars demonstrated a substantive control architecture with measurable gains from its ledger and guard layers. The harness remained effective after a major model substitution and reached 60.00% Pass³ with high success consistency."},"summary":{"punchline":"A transcript-derived ledger and fail-closed pre-flight gate make policy invariants deterministic, invoking plan simulation only for unresolved values.","body":"10cars surrounds one Qwen3-32B tool caller with a compiled behavioral constitution, a success-only intent ledger, and a deterministic gate for schema, ordering, confirmation, idempotence, preference, and cascade checks. When values remain unbound or readings compete, a fourth layer generates three plans, simulates their effects in a lightweight twin, and ranks policy violations and postcondition coverage; otherwise it avoids this deliberation. On a local surrogate stack, adding the first three layers raised Base trial passes from 35/90 to 55/90, while submitted version v4 reached an equal-split composite Pass3 of .267 on a 50-task training subset. The report stresses that absolute scores are not leaderboard-comparable, later safeguards were tested on an adaptively reused 23-task subset, and their confidence intervals include zero."},"metrics":{"pass3":0.6,"passAt3":0.8,"pass1":0.766666666667,"categories":{"base":{"pass3":0.6,"pass_at_3":0.7,"pass1":0.7},"hallucination":{"pass3":0.5,"pass_at_3":0.9,"pass1":0.8},"disambiguation":{"pass3":0.7,"pass_at_3":0.8,"pass1":0.8}},"successfulTrials":65,"successfulTrialsTotal":90,"successConsistency":0.854166666667,"taskLatencyMeanMs":111462.72666666667,"taskLatencyMedianMs":104778.2,"taskLatencyP95Ms":231807.3,"turnLatencyMedianMs":11679.8,"meanTokensPerTrial":294281.3,"estimatedCostPerTrialUsd":0.559572111111,"rank":{"start":4,"end":6,"total":21,"label":"4.-6./21"}}},{"key":"track_1__team-5","track":"track_1","teamId":"team-5","teamName":"Proxima","mainLlm":"GPT-5.5","report":"reports/track_1/team-5.pdf","award":null,"summary":{"punchline":"A coroutine bridge resumes model-written Python across tool round-trips, preserving deterministic policy while avoiding a new LLM call per result.","body":"Proxima has the model emit a Python program whose execution suspends at evaluator tool calls and resumes in the same frame when results return. This coroutine bridge batches independent reads, keeps policy in guarded tool wrappers, and reduces a multi-round task to a median of two model calls despite seven to ten A2A turns. The harness was regression-developed on gpt-oss-120b, then deployed unchanged on GPT-5.5 so stronger interpretation sits above identical policy code. On 125 public tasks with three trials, the development model reportedly reached 93.3% Pass1 and 87.3% Pass3; GPT-5.5 evidence was targeted plus smoke validation, not a full sweep. Other caveats are in-memory worker state and public-API latency that includes network and provider queueing."},"metrics":{"pass3":0.6,"passAt3":0.766666666667,"pass1":0.666666666667,"categories":{"base":{"pass3":0.5,"pass_at_3":0.5,"pass1":0.5},"hallucination":{"pass3":0.9,"pass_at_3":1.0,"pass1":1.0},"disambiguation":{"pass3":0.4,"pass_at_3":0.8,"pass1":0.5}},"successfulTrials":60,"successfulTrialsTotal":90,"successConsistency":0.804347826087,"taskLatencyMeanMs":27139.126666666667,"taskLatencyMedianMs":14067.75,"taskLatencyP95Ms":85765.09999999999,"turnLatencyMedianMs":24.3,"meanTokensPerTrial":102799.90909090909,"estimatedCostPerTrialUsd":0.253328184659,"rank":{"start":4,"end":6,"total":21,"label":"4.-6./21"}}},{"key":"track_1__team-37","track":"track_1","teamId":"team-37","teamName":"ryanlee.ai","mainLlm":"DeepSeek V4 Flash","report":"reports/track_1/team-37.pdf","award":{"award":"Innovation Award","award_order":2,"innovation":"CAR-GUIDE spends additional inference only when an action would change state, surrounding those decisions with deterministic evidence and safety gates.","rationale":"The organizers recognized a distinctive compute-allocation strategy backed by matched development evidence and strong hidden-set performance. The system delivered 60.00% Pass³ while keeping estimated API cost notably low."},"summary":{"punchline":"CAR-GUIDE spends extra samples only on proposed mutations, surrounding them with deterministic capability evidence, advisory gates, and unavailable-result safeguards.","body":"Ryan Lee's CAR-GUIDE applies seven controls at three stages. First-turn capability awareness compares a fixed application manifest with visible tools, while value-free read-only tools are prefetched. At decision time, read-only calls and dialogue use one sample, but proposed state changes receive two additional samples and plurality voting, followed by narrow substitution and necessity gates plus a visible-tool guardrail. Result handling treats unknown fields as unavailable, and a formatter normalizes 24-hour time. Across three full 129-task training batches, the report averages 75.8% macro Pass3 versus 58.5% for a reproduced reference using the same DeepSeek V4 Flash setup. Selective voting improves observed reliability over one sample while using 50.5% fewer primary samples than blanket voting. Evidence is limited to a development-visible training pool; some mechanism ranges overlap, and the manifest path and advisory gates are grouped rather than causally isolated."},"metrics":{"pass3":0.6,"passAt3":0.8,"pass1":0.666666666667,"categories":{"base":{"pass3":0.6,"pass_at_3":0.7,"pass1":0.6},"hallucination":{"pass3":0.7,"pass_at_3":0.9,"pass1":0.7},"disambiguation":{"pass3":0.5,"pass_at_3":0.8,"pass1":0.7}},"successfulTrials":62,"successfulTrialsTotal":90,"successConsistency":0.791666666667,"taskLatencyMeanMs":48935.62888888888,"taskLatencyMedianMs":37825.45,"taskLatencyP95Ms":119944.6,"turnLatencyMedianMs":3818.0,"meanTokensPerTrial":217521.1379310345,"estimatedCostPerTrialUsd":0.009897873469,"rank":{"start":4,"end":6,"total":21,"label":"4.-6./21"}}},{"key":"track_1__team-10","track":"track_1","teamId":"team-10","teamName":"BMAgent","mainLlm":"Claude Opus 4.6","report":"reports/track_1/team-10.pdf","award":null,"summary":{"punchline":"BMAgent lets one configurable LLM propose actions, then rejects schema violations, invented identifiers, stale routes, unsafe repeats, and unsupported completion claims.","body":"BMAgent uses evaluator-supplied schemas as the only executable tool inventory, augments them with compact tool cards, and passes each LLM proposal through deterministic verifiers before returning an A2A response. The checks validate names and arguments, require opaque IDs to originate in prior results, derive conversation state, block duplicate completed actions and repeated searches, and prevent dependent work after unreliable results. The final configuration keeps planner/critic and broad workflow skills disabled, preserving one primary model call per agent turn; its default route is Claude Opus 4.6, while local public validation used DeepSeek V4 Flash. Those development traces report Pass3 of .62 Base, .64 Disambiguation, and .50 Hallucination. They are not hidden-set results, and residual failures center on complex navigation, charging composition, and paraphrases that obscure missing preferences."},"metrics":{"pass3":0.566666666667,"passAt3":0.766666666667,"pass1":0.7,"categories":{"base":{"pass3":0.6,"pass_at_3":0.6,"pass1":0.6},"hallucination":{"pass3":0.6,"pass_at_3":0.8,"pass1":0.8},"disambiguation":{"pass3":0.5,"pass_at_3":0.9,"pass1":0.7}},"successfulTrials":59,"successfulTrialsTotal":90,"successConsistency":0.782608695652,"taskLatencyMeanMs":90885.52555555555,"taskLatencyMedianMs":54077.149999999994,"taskLatencyP95Ms":272960.2,"turnLatencyMedianMs":6873.85,"meanTokensPerTrial":null,"estimatedCostPerTrialUsd":null,"rank":{"start":7,"end":8,"total":21,"label":"7.-8./21"}}},{"key":"track_1__team-39","track":"track_1","teamId":"team-39","teamName":"FAIR","mainLlm":"GPT-5.6 Terra","report":"reports/track_1/team-39.pdf","award":null,"summary":{"punchline":"Planner, proposer, and verifier roles exchange structured evidence under live-schema checks, bounded repair, unknown-result containment, and a five-call depth ceiling.","body":"FAIR's harness runs separately prompted planner, proposer, and verifier roles over a compact evidence state built from the live A2A transcript, policy, schemas, results, preferences, and unresolved fields. The planner records obligations and forbidden assumptions; the proposer emits one next action; the verifier either accepts it or identifies one defect for bounded repair. Runtime code validates names, arguments, types, enums, and nested schema structure, preloads available preferences, prevents literal unknowns from becoming arguments or claims, strips planning helpers, normalizes policy-governed time text, and enforces at most five sequential model calls per step. With Cerebras-hosted gpt-oss-120b, the report gives train/validation Pass3 of 44.2%/44.0% and 458,858 mean tokens per task. Detailed baselines and ablations are omitted because experiments were small and unstable; schema validity also cannot prove that a requested effect is semantically achievable."},"metrics":{"pass3":0.566666666667,"passAt3":0.8,"pass1":0.733333333333,"categories":{"base":{"pass3":0.4,"pass_at_3":0.7,"pass1":0.5},"hallucination":{"pass3":0.9,"pass_at_3":1.0,"pass1":1.0},"disambiguation":{"pass3":0.4,"pass_at_3":0.7,"pass1":0.7}},"successfulTrials":63,"successfulTrialsTotal":90,"successConsistency":0.8125,"taskLatencyMeanMs":133986.32888888888,"taskLatencyMedianMs":102345.04999999999,"taskLatencyP95Ms":304665.3,"turnLatencyMedianMs":9200.4,"meanTokensPerTrial":525494.988764045,"estimatedCostPerTrialUsd":0.666517219803,"rank":{"start":7,"end":8,"total":21,"label":"7.-8./21"}}},{"key":"track_1__team-16","track":"track_1","teamId":"team-16","teamName":"AgentGuardUtil","mainLlm":"Claude Opus 4.8","report":"reports/track_1/team-16.pdf","award":null,"summary":{"punchline":"AgentGuardUtil compiles prose policy into executable obligations that simulate a draft's effects and return exact remedial calls before execution.","body":"AgentGuardUtil frames its LLM planner as a student and a verification harness as the teacher. On the first turn, a runtime compiler converts the supplied natural-language policy into cached typed rules and an executable subset. For each draft, an obligation engine projects the environment after proposed writes, detects still-owed side effects, and emits concrete calls with computed arguments; twenty-five additional gates check identifier provenance, schemas, gather-before-act ordering, confirmation, completion claims, refusals, and future-time reasoning. Hard findings bypass the LLM critic, advisory findings may only be confirmed or discarded, and a bounded revise-and-recheck loop precedes release. Modal voting can select among state-mutating drafts. The report explains the architecture and examples in detail but presents no CAR-bench scores, ablation results, cost measurements, or empirical failure analysis."},"metrics":{"pass3":0.533333333333,"passAt3":0.8,"pass1":0.666666666667,"categories":{"base":{"pass3":0.5,"pass_at_3":0.6,"pass1":0.6},"hallucination":{"pass3":0.7,"pass_at_3":1.0,"pass1":0.9},"disambiguation":{"pass3":0.4,"pass_at_3":0.8,"pass1":0.5}},"successfulTrials":61,"successfulTrialsTotal":90,"successConsistency":0.770833333333,"taskLatencyMeanMs":166137.8477777778,"taskLatencyMedianMs":145943.05,"taskLatencyP95Ms":347960.9,"turnLatencyMedianMs":19218.85,"meanTokensPerTrial":362003.3777777778,"estimatedCostPerTrialUsd":0.811565175,"rank":{"start":9,"end":11,"total":21,"label":"9.-11./21"}}},{"key":"track_1__team-25","track":"track_1","teamId":"team-25","teamName":"shiina18","mainLlm":"DeepSeek V4 Flash","report":"reports/track_1/team-25.pdf","award":null,"summary":{"punchline":"A three-gate harness withholds schema-invalid, preference-ungrounded, or policy-breaking actions, prompting bounded re-proposals before any tool call reaches the evaluator.","body":"Shiina wraps a DeepSeek V4-Flash ReAct agent with an owned 'admit, do not force' prompt and a dispatch-time check node. Schema checks catch unavailable tools or arguments, a narrow LLM judge identifies guessed preference-backed values, and deterministic policy gates enforce preconditions and confirmations; rejected batches are retained with synthetic feedback and re-proposed up to three times. On the public splits, the report says the harness raises macro Pass3 from 47.7% to 60.4% on train and from 43.3% to 54.7% on test at 1.06x baseline latency, with further gains from high reasoning. Base remains flat without reasoning, and remaining limitations include workaround behavior on missing navigation-edit capabilities and ambiguity in some benchmark instructions."},"metrics":{"pass3":0.533333333333,"passAt3":0.833333333333,"pass1":0.666666666667,"categories":{"base":{"pass3":0.5,"pass_at_3":0.6,"pass1":0.5},"hallucination":{"pass3":0.8,"pass_at_3":1.0,"pass1":0.9},"disambiguation":{"pass3":0.3,"pass_at_3":0.9,"pass1":0.6}},"successfulTrials":62,"successfulTrialsTotal":90,"successConsistency":0.74,"taskLatencyMeanMs":39264.14555555556,"taskLatencyMedianMs":29937.0,"taskLatencyP95Ms":87210.5,"turnLatencyMedianMs":4157.0,"meanTokensPerTrial":117028.97777777778,"estimatedCostPerTrialUsd":0.005492975336,"rank":{"start":9,"end":11,"total":21,"label":"9.-11./21"}}},{"key":"track_1__team-23","track":"track_1","teamId":"team-23","teamName":"Sid&Sanika","mainLlm":"Gemini 3.5 Flash","report":"reports/track_1/team-23.pdf","award":null,"summary":{"punchline":"A deterministic policy layer injects prerequisites and side effects, then uses cache-first or EVPI-guided questions to resolve ambiguity consistently.","body":"Sid&Sanika wrap Gemini 2.5 Flash tool proposals in ordered checks for tool existence, confirmation, prerequisite state, missing arguments or result fields, preference lookup, mutual exclusion, post-action side effects, and semantic completion claims. Disambiguation first uses vetted cached questions; unresolved cases generate interpretations and choose the yes/no question that best splits them, then phrase it at temperature zero. A final self-consistency verifier samples repairs when policy or completion claims fail. On the public split, the report compares against the paper's same-model baseline: Hallucination Pass3 rises from 22% to 42% and Disambiguation from 22% to 36%, while Base is 46% versus 48% despite higher Pass@1 and Pass@3. A stated gap is that fully specified but wrong ambiguous calls bypass preference auto-injection, which currently triggers only on incomplete calls."},"metrics":{"pass3":0.533333333333,"passAt3":0.9,"pass1":0.733333333333,"categories":{"base":{"pass3":0.5,"pass_at_3":0.9,"pass1":0.8},"hallucination":{"pass3":0.7,"pass_at_3":1.0,"pass1":0.9},"disambiguation":{"pass3":0.4,"pass_at_3":0.8,"pass1":0.5}},"successfulTrials":65,"successfulTrialsTotal":90,"successConsistency":0.703703703704,"taskLatencyMeanMs":88196.46555555557,"taskLatencyMedianMs":75069.55,"taskLatencyP95Ms":173345.0,"turnLatencyMedianMs":4548.0,"meanTokensPerTrial":225151.76666666666,"estimatedCostPerTrialUsd":0.201444421667,"rank":{"start":9,"end":11,"total":21,"label":"9.-11./21"}}},{"key":"track_1__team-12","track":"track_1","teamId":"team-12","teamName":"SBL","mainLlm":"Claude Sonnet 4.6","report":"reports/track_1/team-12.pdf","award":null,"summary":{"punchline":"A provenance-aware Decision Manager authorizes Sonnet proposals with deterministic evidence checks, sampling alternatives only on turns classified as high risk.","body":"SBL records goals, constraints, preferences, observations, and the source of each value, then checks Claude Sonnet 4.6 proposals for current capability, required evidence, ambiguity, policy order, confirmation, completion, and disclosure. Low-risk turns use one draft; high-risk turns generate up to three framed candidates and deterministically select the fewest-violation option. On the complete 125-task public test set, the frozen image reports 63.3% official Pass3 and 87.3% Pass@3, with split Pass3 of 74% Base, 52% Hallucination, and 64% Disambiguation. A fixed 18-task development slice improved from 55.6% to 94.4% Pass3, but used staged, non-factorial comparisons. The main caveats are a 31.1-point development-to-public gap and only 18.2% Pass3 when required tool response fields are missing."},"metrics":{"pass3":0.5,"passAt3":0.766666666667,"pass1":0.7,"categories":{"base":{"pass3":0.5,"pass_at_3":0.7,"pass1":0.6},"hallucination":{"pass3":0.6,"pass_at_3":0.9,"pass1":0.9},"disambiguation":{"pass3":0.4,"pass_at_3":0.7,"pass1":0.6}},"successfulTrials":56,"successfulTrialsTotal":90,"successConsistency":0.717391304348,"taskLatencyMeanMs":81559.50333333333,"taskLatencyMedianMs":44411.65,"taskLatencyP95Ms":252654.3,"turnLatencyMedianMs":7717.9,"meanTokensPerTrial":149187.04444444444,"estimatedCostPerTrialUsd":0.217231864167,"rank":{"start":12,"end":13,"total":21,"label":"12.-13./21"}}},{"key":"track_1__team-6","track":"track_1","teamId":"team-6","teamName":"VoxGuard","mainLlm":"GPT-5.4","report":"reports/track_1/team-6.pdf","award":null,"summary":{"punchline":"VoxGuard routes recurring intents through zero-LLM state-machine macros and subjects every remaining GPT-5.4 action to a deterministic guard chain.","body":"VoxGuard separates recurring tasks from open-ended planning. A macro router maps matched intents to hand-verified state machines whose values are derived from dialogue, preferences, policy, and live tools; unmatched cases go to GPT-5.4 and then through about fifteen guards for capability, prerequisite, ordering, disclosure, and state semantics. A four-level verification pyramid covers unit rules, 460 paraphrased routing snapshots, targeted end-to-end tasks, and full rounds. The submitted public-training-split round reports 123/129 tasks, a 94.7% task-type-average Pass1, $20.3 list-price-equivalent cost, and 21 tasks completed without LLM inference. The report notes development and measurement used the same public split, residual failures cluster around route-choice and other hard workflows, and its projected 50% tier-routing cost reduction was not measured end to end."},"metrics":{"pass3":0.5,"passAt3":0.666666666667,"pass1":0.633333333333,"categories":{"base":{"pass3":0.4,"pass_at_3":0.4,"pass1":0.4},"hallucination":{"pass3":0.7,"pass_at_3":1.0,"pass1":1.0},"disambiguation":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.5}},"successfulTrials":54,"successfulTrialsTotal":90,"successConsistency":0.85,"taskLatencyMeanMs":65034.18111111111,"taskLatencyMedianMs":45563.45,"taskLatencyP95Ms":176469.5,"turnLatencyMedianMs":6589.2,"meanTokensPerTrial":88484.3661971831,"estimatedCostPerTrialUsd":0.179584308099,"rank":{"start":12,"end":13,"total":21,"label":"12.-13./21"}}},{"key":"track_1__team-14","track":"track_1","teamId":"team-14","teamName":"NickWagener","mainLlm":"Claude Sonnet 4.6","report":"reports/track_1/team-14.pdf","award":null,"summary":{"punchline":"Glassbox confines the LLM to planning and prose while a seven-stage ledger-driven shell verifies policies, provenance, ambiguity, and response claims.","body":"Glassbox uses a provenance ledger and seven-stage state machine in which only PLAN and RESPOND invoke the LLM; capability checks, eleven fully deterministic policy classes, tool preconditions, confirmation, and numerical claim verification run as code. Soft findings trigger at most two redrafts, hard findings block or replace output, and a five-level cascade handles ambiguous slots through policy, user values, preferences, heuristics, then clarification. A naked Sonnet 4.6 baseline scored 31/60 Pass3, while an early over-strict Glassbox fell to 27/60; targeted severity fixes recovered a failed task, but no full post-fix 60-task run was completed. The report also finds Sonnet and Opus nearly tied at 9/18 versus 8/18 under one shell and records zero policy-authorization errors across 894 runs, while acknowledging severe unseen-task disambiguation overfitting."},"metrics":{"pass3":0.466666666667,"passAt3":0.666666666667,"pass1":0.633333333333,"categories":{"base":{"pass3":0.3,"pass_at_3":0.5,"pass1":0.5},"hallucination":{"pass3":0.7,"pass_at_3":0.8,"pass1":0.8},"disambiguation":{"pass3":0.4,"pass_at_3":0.7,"pass1":0.6}},"successfulTrials":51,"successfulTrialsTotal":90,"successConsistency":0.775,"taskLatencyMeanMs":102439.49333333333,"taskLatencyMedianMs":97206.5,"taskLatencyP95Ms":206203.4,"turnLatencyMedianMs":12088.25,"meanTokensPerTrial":142695.15555555557,"estimatedCostPerTrialUsd":0.195942895833,"rank":{"start":14,"end":14,"total":21,"label":"14./21"}}},{"key":"track_1__team-30","track":"track_1","teamId":"team-30","teamName":"Codexxxx","mainLlm":"Claude Opus 4.8","report":"reports/track_1/team-30.pdf","award":null,"summary":{"punchline":"A route selector sends each request through direct, guarded, or risk handling, with at most one reflected revision before visible-interface validation.","body":"Codexxxx presents a bounded A2A agent that builds context only from the current conversation, live tool names and schemas, and returned observations. A router selects direct execution, guarded contract checking, or a risk path. The executor proposes either text or a tool call; validation rejects unavailable operations and unsupported values, while the risk path permits one reflection and one revised proposal before revalidation. If essential evidence remains absent, the agent reports the limitation instead of inventing a value or claiming success. The report deliberately makes no performance claim: development used only limited targeted Track 1 checks, with no complete benchmark run, repeated-trial study, baseline comparison, latency, or cost measurement. Track 2 experiments informed design choices but are explicitly excluded as evidence for this Track 1 submission."},"metrics":{"pass3":0.433333333333,"passAt3":0.666666666667,"pass1":0.6,"categories":{"base":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.6},"hallucination":{"pass3":0.5,"pass_at_3":0.8,"pass1":0.7},"disambiguation":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.5}},"successfulTrials":51,"successfulTrialsTotal":90,"successConsistency":0.775,"taskLatencyMeanMs":44727.31888888889,"taskLatencyMedianMs":32526.65,"taskLatencyP95Ms":137854.3,"turnLatencyMedianMs":5316.4,"meanTokensPerTrial":169808.67045454544,"estimatedCostPerTrialUsd":0.333689085227,"rank":{"start":15,"end":17,"total":21,"label":"15.-17./21"}}},{"key":"track_1__team-32","track":"track_1","teamId":"team-32","teamName":"Molti Tasking","mainLlm":"GLM 5.2 via OpenRouter","report":"reports/track_1/team-32.pdf","award":null,"summary":{"punchline":"A narrow self-check makes every claimed action present a successful tool-call ticket, rewriting unsupported completion text without suppressing genuine actions.","body":"Molti Tasking's Fahrkartenkontrolle wraps a temperature-zero open-weight GLM with six German grounding-and-default rules and a final LLM self-check. The prompt prioritizes tool-grounded claims, minimal action, preference-first ambiguity resolution, policy defaults, immediate confirmed action, and short English replies. Before user-facing text exits, the checker compares it with successful call IDs and rewrites only unsupported completion claims or confirmations that never executed; it does not cancel tool actions. On the full public test split, the report says Pass3 rises from 52.0% to 71.3%, mainly through Hallucination improvement from 22% to 76%, at roughly 30% more tokens. Voting tripled token use without gain, German versus translated rules was indistinguishable within replication noise, and the champion retains an 18-point Pass@3-Pass3 consistency gap; most ablations were single runs with 4.4-8.9-point replication spreads."},"metrics":{"pass3":0.433333333333,"passAt3":0.7,"pass1":0.533333333333,"categories":{"base":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.4},"hallucination":{"pass3":0.7,"pass_at_3":0.8,"pass1":0.7},"disambiguation":{"pass3":0.2,"pass_at_3":0.7,"pass1":0.5}},"successfulTrials":49,"successfulTrialsTotal":90,"successConsistency":0.666666666667,"taskLatencyMeanMs":94222.02111111111,"taskLatencyMedianMs":44004.3,"taskLatencyP95Ms":291092.0,"turnLatencyMedianMs":6365.3,"meanTokensPerTrial":113305.76666666666,"estimatedCostPerTrialUsd":0.072222962222,"rank":{"start":15,"end":17,"total":21,"label":"15.-17./21"}}},{"key":"track_1__team-40","track":"track_1","teamId":"team-40","teamName":"Quarry","mainLlm":"Claude Sonnet 5","report":"reports/track_1/team-40.pdf","award":null,"summary":{"punchline":"Quarry reconstructs call-ID-bound evidence, permits one strictly revalidated correction, and emits causal receipts tying every intervention to visible state and results.","body":"Quarry V14 wraps Claude Sonnet 5 with a deterministic controller that rebuilds a typed ledger from visible messages, advertised schemas, proposed call IDs, and explicitly successful matching results. Pre-dispatch predicates catch malformed or unavailable calls, missing arguments, identifier-namespace errors, contradictory navigation state, and absent confirmation. Mechanical fixes or one same-model correction are strictly revalidated; remaining invalid calls are withheld. A call-ID-bound postcondition can append the policy-required multi-stop route disclosure without another model call, and receipts preserve the rejected proposal, evidence, correction, dispatch, matched result, and final event. On a frozen 25-task public panel, V14 scores 14/25 Pass3 versus stock's 12/25 and earlier V7-E3's 15/25. The report explicitly notes that V14's positive task flips lacked interventions, the sample is small and public, and broader guards converted no strict task, so it claims auditability rather than causal aggregate uplift."},"metrics":{"pass3":0.433333333333,"passAt3":0.633333333333,"pass1":0.533333333333,"categories":{"base":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.4},"hallucination":{"pass3":0.5,"pass_at_3":0.7,"pass1":0.6},"disambiguation":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.6}},"successfulTrials":51,"successfulTrialsTotal":90,"successConsistency":0.842105263158,"taskLatencyMeanMs":30821.975555555553,"taskLatencyMedianMs":21194.65,"taskLatencyP95Ms":67269.0,"turnLatencyMedianMs":3432.7,"meanTokensPerTrial":136852.06666666668,"estimatedCostPerTrialUsd":0.107659972778,"rank":{"start":15,"end":17,"total":21,"label":"15.-17./21"}}},{"key":"track_1__team-24","track":"track_1","teamId":"team-24","teamName":"Choosagi","mainLlm":"DeepSeek V4 Flash","report":"reports/track_1/team-24.pdf","award":null,"summary":{"punchline":"Choosagi puts twelve deterministic validator families around DeepSeek drafts, using error-time coaching and honest fallbacks without ever inventing tool calls.","body":"Choosagi reconstructs shadow vehicle state from evaluator-visible traffic and checks every DeepSeek V4 Flash draft for schemas, confirmation, physical and policy preconditions, evidence-backed values, ask-before-preference errors, retry bans, and narrative honesty. Violations trigger at most two targeted redrafts; exhaustion strips illegal calls, preserves valid clarification, or produces a topic-specific refusal. On 125 public-test tasks, the report gives raw Pass3 of 52.7% (68% Base, 58% Hallucination, 32% Disambiguation) at $3.84 across five scored legs. A 69.9% contamination-clean estimate excludes tasks affected by exhausted shared Gemini quota and rests on a much smaller Disambiguation sample. Ablations found always-on coaching hurt, while tasks with at least ten guard interventions passed only 34.8% versus 79.4% below that threshold; a full guard-off ablation remains future work."},"metrics":{"pass3":0.366666666667,"passAt3":0.733333333333,"pass1":0.566666666667,"categories":{"base":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.4},"hallucination":{"pass3":0.3,"pass_at_3":0.8,"pass1":0.7},"disambiguation":{"pass3":0.4,"pass_at_3":0.8,"pass1":0.6}},"successfulTrials":50,"successfulTrialsTotal":90,"successConsistency":0.636363636364,"taskLatencyMeanMs":55553.758888888886,"taskLatencyMedianMs":43631.6,"taskLatencyP95Ms":137933.6,"turnLatencyMedianMs":4051.6,"meanTokensPerTrial":207418.61111111112,"estimatedCostPerTrialUsd":0.009561706459,"rank":{"start":18,"end":19,"total":21,"label":"18.-19./21"}}},{"key":"track_1__team-7","track":"track_1","teamId":"team-7","teamName":"OneInAMinion","mainLlm":"GPT-5.4 nano","report":"reports/track_1/team-7.pdf","award":null,"summary":{"punchline":"A four-stage retrieval pipeline shrinks the 58-tool catalog before a small model enters its ReAct execution loop.","body":"OneInAMinion places retrieval before tool execution for a ChatGPT 4.5 nano agent. Three LLM stages extract intent and entities, rerank retrieved candidates, and produce an ordered query plan; between them, BGE-small embeddings select the top ten tools from names, descriptions, and parameter text. An optional graph mode expands retrieval across a 58-node, 509-edge tool ontology, while labeled mode adds policy hints to tool descriptions. The resulting plan and reduced catalog guide a standard temperature-zero ReAct loop, with all-tool initialization as a graceful fallback if a pipeline stage fails. The report describes evaluation across Base, Hallucination, and Disambiguation tasks and the Pass@k/Pass^k metrics, but it provides no measured scores or comparison table, so the claimed benefit remains architectural rather than empirically quantified."},"metrics":{"pass3":0.366666666667,"passAt3":0.566666666667,"pass1":0.433333333333,"categories":{"base":{"pass3":0.2,"pass_at_3":0.3,"pass1":0.2},"hallucination":{"pass3":0.7,"pass_at_3":0.9,"pass1":0.8},"disambiguation":{"pass3":0.2,"pass_at_3":0.5,"pass1":0.3}},"successfulTrials":42,"successfulTrialsTotal":90,"successConsistency":0.735294117647,"taskLatencyMeanMs":37270.15333333333,"taskLatencyMedianMs":26091.4,"taskLatencyP95Ms":87537.1,"turnLatencyMedianMs":3046.25,"meanTokensPerTrial":31097.68888888889,"estimatedCostPerTrialUsd":0.002021349778,"rank":{"start":18,"end":19,"total":21,"label":"18.-19./21"}}},{"key":"track_1__team-26","track":"track_1","teamId":"team-26","teamName":"KIWIS","mainLlm":"DeepSeek V4 Flash","report":"reports/track_1/team-26.pdf","award":null,"summary":{"punchline":"A typed capability graph uses personalized PageRank to retrieve tools together with their policies, schemas, examples, and structural dependencies.","body":"KIWIS builds a knowledge graph whose nodes represent tools, domains, parameters, outputs, policies, logic clauses, action steps, and examples. Query and state embeddings seed per-type retrieval; weighted personalized PageRank propagates relevance, specificity scoring discounts structural hubs, and repeated-call penalties help escape stalls. The top-ranked tools are enriched with connected policies and schemas before being injected into Gemini 2.5 Flash. The complete pipeline also includes a comprehensive system prompt plus time-format and visible-contract checks. Against the reported Gemini baseline, average Pass3 rises from 34% to 48%, driven by Base and Disambiguation, while Hallucination falls from 32% to 26%. The authors caution that no ablation isolates graph retrieval from prompt and harness changes, and the 35-point Pass@3-Pass3 gap indicates substantial repeatability weakness."},"metrics":{"pass3":0.3,"passAt3":0.6,"pass1":0.5,"categories":{"base":{"pass3":0.3,"pass_at_3":0.5,"pass1":0.4},"hallucination":{"pass3":0.5,"pass_at_3":0.8,"pass1":0.8},"disambiguation":{"pass3":0.1,"pass_at_3":0.5,"pass1":0.3}},"successfulTrials":43,"successfulTrialsTotal":90,"successConsistency":0.694444444444,"taskLatencyMeanMs":139302.1588888889,"taskLatencyMedianMs":89610.75,"taskLatencyP95Ms":455596.4,"turnLatencyMedianMs":9532.75,"meanTokensPerTrial":129412.51111111112,"estimatedCostPerTrialUsd":0.006559452006,"rank":{"start":20,"end":20,"total":21,"label":"20./21"}}},{"key":"track_1__team-9","track":"track_1","teamId":"team-9","teamName":"SparkShield","mainLlm":"Gemini 3.5 Flash","report":"reports/track_1/team-9.pdf","award":null,"summary":{"punchline":"CAR-Guard grounds intent without seeing capabilities, then binds fixed recipes to live schemas and requires goal-scoped evidence before every action.","body":"SparkShield treats Gemini 3.5 Flash output as an untrusted proposal. It first derives an inventory-blind Goal DAG, binds one of 42 audited recipes across 25 domains to the current JSON schemas, and records typed evidence with goal, call, turn, freshness, and state-version provenance. Conditional closure freezes a complete action bundle before writes, while twelve pre-commit checks cover authorization, schemas, ambiguity, policy, confirmation, idempotency, and budget; protocol state also handles replay, cancellation, and duplicate side effects. The frozen release passed 2,460 tests and 46 subtests, with two disclosed official-core failures. A pre-fix build passed 12/15 single-trial tasks, but the final official run stopped on an evaluator location error before any agent turn, leaving no final-commit Pass3 or complete benchmark result."},"metrics":{"pass3":0.1,"passAt3":0.3,"pass1":0.233333333333,"categories":{"base":{"pass3":0.2,"pass_at_3":0.3,"pass1":0.3},"hallucination":{"pass3":0.1,"pass_at_3":0.5,"pass1":0.3},"disambiguation":{"pass3":0.0,"pass_at_3":0.1,"pass1":0.1}},"successfulTrials":17,"successfulTrialsTotal":90,"successConsistency":0.444444444444,"taskLatencyMeanMs":34649.21,"taskLatencyMedianMs":20224.5,"taskLatencyP95Ms":107386.4,"turnLatencyMedianMs":4220.450000000001,"meanTokensPerTrial":59326.30303030303,"estimatedCostPerTrialUsd":0.130421321023,"rank":{"start":21,"end":21,"total":21,"label":"21./21"}}},{"key":"track_2__team-4","track":"track_2","teamId":"team-4","teamName":"Proxima","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-4.pdf","award":{"award":"Cerebras Award","award_order":4,"innovation":"A coroutine bridge suspends model-generated Python at tool calls and resumes the same program when results arrive, reducing repeated inference round-trips.","rationale":"Proxima paired an original compute-aware architecture with the strongest Track 2 result: 60.00% Pass³. It ranked first in performance and ranked efficiency while using only a few model calls across multi-turn tool workflows."},"summary":{"punchline":"A coroutine suspends model-generated Python at tool calls and resumes the same stack on results, collapsing dependent A2A round-trips into few inferences.","body":"Proxima's agent asks gpt-oss-120b to emit a Python program rather than one next tool action. A persistent per-context interpreter blocks when a wrapper calls an evaluator tool, sends the official call, and resumes the same stack frame with returned results, so one model invocation can branch across multiple dependent or batched tool rounds. Deterministic policies are compiled into guarded wrappers, confirmation state machines, response obligations, unknown-value sentinels, and turn-scoped failure tracking; semantic intent remains with the model. On the 125-task public test split, the report claims Pass1 93.3%, Pass3 87.3%, median two model calls over seven A2A turns, and 1.8 seconds median model latency. A stable prompt prefix produces high warm-cache rates. Limitations include in-memory worker state that cannot survive process restarts and residual simulator/judge variance; the report provides no separate ablation isolating each policy-as-code component."},"metrics":{"pass3":0.6,"passAt3":0.666666666667,"pass1":0.666666666667,"categories":{"base":{"pass3":0.5,"pass_at_3":0.5,"pass1":0.5},"hallucination":{"pass3":1.0,"pass_at_3":1.0,"pass1":1.0},"disambiguation":{"pass3":0.3,"pass_at_3":0.5,"pass1":0.5}},"successfulTrials":57,"successfulTrialsTotal":90,"successConsistency":0.925,"taskLatencyMeanMs":5648.447777777777,"taskLatencyMedianMs":3143.85,"taskLatencyP95Ms":12586.9,"turnLatencyMedianMs":24.6,"meanTokensPerTrial":112992.82222222222,"estimatedCostPerTrialUsd":0.040779292222,"rank":{"start":1,"end":1,"total":13,"label":"1./13"}}},{"key":"track_2__team-36","track":"track_2","teamId":"team-36","teamName":"FreudeDrive","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-36.pdf","award":null,"summary":{"punchline":"Adaptive role-diverse candidates run in one parallel stage, escalating to deterministic adjudication and repair only when votes or guards conflict.","body":"Guarded Cerebras Self-Consistency classifies each visible situation and launches one to three policy-first, tool-first, or hallucination-aware candidates in parallel. Canonical voting and deterministic checks cover schemas, argument provenance, policy prerequisites, confirmation scope, scoped preferences, navigation state, and repeated failures; disagreement or guard findings trigger bounded high-effort adjudication and repair. A central gate clamps sequential depth to five and adjusts breadth using a per-context token ledger. The frozen system reports 18/24 Pass3 on a three-trial development panel and 11/12 on a one-shot holdout, averaging about 221k and 248k tokens respectively with exact accounting. The report limits these claims to small panels, noting weaker Base and Disambiguation consistency, long navigation tasks, conservative false blocking, and individual long trajectories that may exceed the average-oriented token allowance."},"metrics":{"pass3":0.5,"passAt3":0.766666666667,"pass1":0.633333333333,"categories":{"base":{"pass3":0.4,"pass_at_3":0.6,"pass1":0.4},"hallucination":{"pass3":0.9,"pass_at_3":1.0,"pass1":1.0},"disambiguation":{"pass3":0.2,"pass_at_3":0.7,"pass1":0.5}},"successfulTrials":57,"successfulTrialsTotal":90,"successConsistency":0.739130434783,"taskLatencyMeanMs":12091.065555555555,"taskLatencyMedianMs":9824.35,"taskLatencyP95Ms":23936.8,"turnLatencyMedianMs":1722.4,"meanTokensPerTrial":342299.6777777778,"estimatedCostPerTrialUsd":0.134364998333,"rank":{"start":2,"end":2,"total":13,"label":"2./13"}}},{"key":"track_2__team-27","track":"track_2","teamId":"team-27","teamName":"Codexxxx","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-27.pdf","award":null,"summary":{"punchline":"A request-conditioned dependency gate rejects unsupported or unobserved operations at zero model cost, then routes only feasible requests to bounded inference.","body":"The submission separates structural limit detection from semantic action generation. Before every generation step, a deterministic gate matches the current request against live tool schemas and recent results, checking 22 capability predicates and 11 unknown-result predicates; missing dependencies produce a transparent zero-call response. Supported requests enter a router choosing direct, contract-guard, or risk-reflection modes, followed by a bounded executor, one malformed-output retry, and optional reflection, with maximum sequential depth four. Router + Guard reports 98/125 on one full public-test pass, using 87.1k tokens and 9.58 seconds of successful LLM latency per task; gains concentrate in Hallucination. The report cautions that the public split informed development, only one final run was completed, and Disambiguation remained weakest, so no Router + Guard Pass3 or hidden-set claim is made."},"metrics":{"pass3":0.366666666667,"passAt3":0.5,"pass1":0.4,"categories":{"base":{"pass3":0.3,"pass_at_3":0.4,"pass1":0.3},"hallucination":{"pass3":0.6,"pass_at_3":0.7,"pass1":0.6},"disambiguation":{"pass3":0.2,"pass_at_3":0.4,"pass1":0.3}},"successfulTrials":39,"successfulTrialsTotal":90,"successConsistency":0.8,"taskLatencyMeanMs":9862.082222222223,"taskLatencyMedianMs":6935.05,"taskLatencyP95Ms":25866.0,"turnLatencyMedianMs":1272.9,"meanTokensPerTrial":131908.7837837838,"estimatedCostPerTrialUsd":0.061289249324,"rank":{"start":3,"end":4,"total":13,"label":"3.-4./13"}}},{"key":"track_2__team-29","track":"track_2","teamId":"team-29","teamName":"DRIFT","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-29.pdf","award":null,"summary":{"punchline":"DRIFT spends model calls only after deterministic phase, traceability, and capability-catalog guards flag risk, enforcing a shared five-call budget.","body":"DRIFT uses schema-constrained action generation with enforcement retries, deterministic checks for phase separation, literal argument provenance, navigation state, and placeholders, then a risk-gated verifier and bounded revision. A shared per-step counter allocates at most five sequential calls across all stages. Its static capability catalog is diffed against the live tool set to expose absent tools in the prompt, which the report identifies as the largest Hallucination gain. Cumulative full-run configurations move from 43.3% to 58.7% Pass3, with a confirmation run at 56.7% and roughly 92k tokens per task. However, the exact submitted source later scored 47.3% in another full run; the report attributes this to substantial run noise. It also notes public-split adaptation, catalog prior knowledge, and a third-party simulator configuration."},"metrics":{"pass3":0.366666666667,"passAt3":0.5,"pass1":0.5,"categories":{"base":{"pass3":0.3,"pass_at_3":0.3,"pass1":0.3},"hallucination":{"pass3":0.7,"pass_at_3":0.8,"pass1":0.8},"disambiguation":{"pass3":0.1,"pass_at_3":0.4,"pass1":0.4}},"successfulTrials":41,"successfulTrialsTotal":90,"successConsistency":0.866666666667,"taskLatencyMeanMs":7219.813333333333,"taskLatencyMedianMs":6073.7,"taskLatencyP95Ms":15446.1,"turnLatencyMedianMs":939.0,"meanTokensPerTrial":132963.03333333333,"estimatedCostPerTrialUsd":0.050134995,"rank":{"start":3,"end":4,"total":13,"label":"3.-4./13"}}},{"key":"track_2__team-38","track":"track_2","teamId":"team-38","teamName":"FAIR","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-38.pdf","award":null,"summary":{"punchline":"FAIR separates planner, proposer, and verifier roles while runtime code contains unknowns, validates live schemas, and bounds defect-specific repair.","body":"FAIR's plan-propose-verify harness gives separate role prompts a compact evidence state, live schemas, policy obligations, completion criteria, and forbidden assumptions. Runtime governance annotates plan surfaces, preloads available preferences, preserves literal unknowns as unresolved evidence, validates every proposed call, removes private planning helpers, and permits only defect-specific bounded repair before a grounded fallback. The normal path uses planner, proposer, and verifier calls; a shared counter caps any A2A step at five sequential calls. Three public train and validation repeats report 63.6% and 62.1% mean accuracy, with 44.2% and 44.0% Pass3, while mean usage is 458,858 tokens per task. The report identifies semantic capability sufficiency as the largest remaining gap: live-schema validity cannot prove the requested effect is achievable, and complete deterministic policy encoding lacked reliable gains."},"metrics":{"pass3":0.333333333333,"passAt3":0.6,"pass1":0.5,"categories":{"base":{"pass3":0.2,"pass_at_3":0.3,"pass1":0.2},"hallucination":{"pass3":0.6,"pass_at_3":1.0,"pass1":0.9},"disambiguation":{"pass3":0.2,"pass_at_3":0.5,"pass1":0.4}},"successfulTrials":41,"successfulTrialsTotal":90,"successConsistency":0.638888888889,"taskLatencyMeanMs":31022.897777777776,"taskLatencyMedianMs":27521.050000000003,"taskLatencyP95Ms":67449.1,"turnLatencyMedianMs":3823.65,"meanTokensPerTrial":552760.3444444444,"estimatedCostPerTrialUsd":0.216548191667,"rank":{"start":5,"end":6,"total":13,"label":"5.-6./13"}}},{"key":"track_2__team-33","track":"track_2","teamId":"team-33","teamName":"Rosebud","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-33.pdf","award":{"award":"Cerebras Award","award_order":5,"innovation":"Rosebud allocates extra samples according to action irreversibility, requiring exact consensus for mutations while keeping read-only work inexpensive.","rationale":"The organizers selected a genuinely Track 2-specific compute-allocation method. Its mutation consensus was active in the hidden evaluation and produced a clear same-model reliability gain, especially on limit-awareness tasks."},"summary":{"punchline":"Rosebud allocates compute by irreversibility: prefetch free reads, require 2-of-3 exact consensus for mutations, and ration clarification.","body":"Rosebud's harness prefetches schema-valid read-only calls, applies deterministic provenance, schema, loop, and policy guards, and samples two additional independent drafts only when the proposed action mutates state. A deterministic 2-of-3 vote over exact tool-and-argument signatures can replace the original draft; clarification is capped at one injected question per episode. On a 101-task, three-trial split with Gemini roles, the report gives 68/101 Pass3 versus 50/101 for the stock baseline, at 1.43 calls per action decision and about 123k tokens per task. Ablations found broader consensus, self-critique, mode routing, and freer clarification neutral or harmful. Caveats include 16 non-terminating read spirals, sensitivity to simulator choice, and no hard per-step counter despite an observed maximum sequential depth of four."},"metrics":{"pass3":0.333333333333,"passAt3":0.5,"pass1":0.466666666667,"categories":{"base":{"pass3":0.1,"pass_at_3":0.2,"pass1":0.2},"hallucination":{"pass3":0.7,"pass_at_3":0.8,"pass1":0.8},"disambiguation":{"pass3":0.2,"pass_at_3":0.5,"pass1":0.4}},"successfulTrials":38,"successfulTrialsTotal":90,"successConsistency":0.766666666667,"taskLatencyMeanMs":10307.504444444445,"taskLatencyMedianMs":7325.55,"taskLatencyP95Ms":23127.5,"turnLatencyMedianMs":992.4,"meanTokensPerTrial":174694.22222222222,"estimatedCostPerTrialUsd":0.065606777778,"rank":{"start":5,"end":6,"total":13,"label":"5.-6./13"}}},{"key":"track_2__team-11","track":"track_2","teamId":"team-11","teamName":"June","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-11.pdf","award":null,"summary":{"punchline":"Three zero-call gates enforce preference grounding, live availability, and policy preconditions before execution, replacing stochastic verification with deterministic checks.","body":"June builds on the starter planner/executor, using high reasoning for private planning and medium reasoning for execution, but shifts repeatable decisions into deterministic code. A preference-first gate forces stored-preference and state reads before guessed values or clarification; an availability gate rejects absent tools, invalid parameters or enums, and literal unknown results; policy gates enforce prior lookups, ordering, and format obligations. Length-limited generations receive bounded lower-effort retries, and token limits are monitoring-only. The harness reports a public-test macro Pass3 of 0.493, up from a bare-model 0.280, at 155K mean tokens and about 10.5 seconds LLM latency per run. Self-consistency, response grounding, and best-of-N all failed to improve Pass3. The authors tuned on the public test split and validated on train, so they acknowledge the headline test numbers are mildly optimistic; remaining errors sit in semantic state-value reasoning and free-text fabrication."},"metrics":{"pass3":0.3,"passAt3":0.7,"pass1":0.566666666667,"categories":{"base":{"pass3":0.3,"pass_at_3":0.4,"pass1":0.3},"hallucination":{"pass3":0.4,"pass_at_3":1.0,"pass1":0.8},"disambiguation":{"pass3":0.2,"pass_at_3":0.7,"pass1":0.6}},"successfulTrials":44,"successfulTrialsTotal":90,"successConsistency":0.547619047619,"taskLatencyMeanMs":13161.813333333334,"taskLatencyMedianMs":12255.15,"taskLatencyP95Ms":26527.0,"turnLatencyMedianMs":1022.8,"meanTokensPerTrial":190882.57777777777,"estimatedCostPerTrialUsd":0.076831786667,"rank":{"start":7,"end":7,"total":13,"label":"7./13"}}},{"key":"track_2__team-41","track":"track_2","teamId":"team-41","teamName":"wfg_2","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-41.pdf","award":null,"summary":{"punchline":"Typed obligations retain workflow ownership across turns, while scoped facts and evidence contracts let deterministic executors authorize side effects.","body":"The agent uses gpt-oss-120b for semantic framing and, when ownership is ambiguous, bounded composition of existing workflows. Validated actions become persistent typed obligations with dependencies, fact roles, owner workflows, and completion contracts. A scoped fact store, policy graph, 37 workflows, 57 atomic capabilities, and deterministic executors handle calculations, prerequisites, tool sequencing, and side effects; completion requires tool evidence matching the requested target. All model-facing components share a five-call budget, while selective schemas, policy retrieval, and result compaction reduce prompt size. The frozen source passed 1,918 tests plus 140 generated subtests and 145/254 public scenarios in one raw trial, averaging 44.7k tokens. No Pass3 is claimed; manual catalogs, weak Disambiguation, and a scheduler edge case that can drop independent sibling work are acknowledged."},"metrics":{"pass3":0.233333333333,"passAt3":0.5,"pass1":0.3,"categories":{"base":{"pass3":0.2,"pass_at_3":0.4,"pass1":0.2},"hallucination":{"pass3":0.3,"pass_at_3":0.6,"pass1":0.3},"disambiguation":{"pass3":0.2,"pass_at_3":0.5,"pass1":0.4}},"successfulTrials":32,"successfulTrialsTotal":90,"successConsistency":0.566666666667,"taskLatencyMeanMs":7561.582222222222,"taskLatencyMedianMs":3865.3,"taskLatencyP95Ms":23902.600000000002,"turnLatencyMedianMs":24.7,"meanTokensPerTrial":48937.17647058824,"estimatedCostPerTrialUsd":0.056432005882,"rank":{"start":8,"end":8,"total":13,"label":"8./13"}}},{"key":"track_2__team-13","track":"track_2","teamId":"team-13","teamName":"SBL","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-13.pdf","award":null,"summary":{"punchline":"A risk-tiered planner-executor sits behind zero-call deterministic controllers and evidence guards, keeping every public step within three sequential model calls.","body":"SBL wraps gpt-oss-120b in ordered deterministic controllers, a risk-tiered planner-executor, a Grounded Subgoal Execution Graph, and schema, evidence, policy, and completion guards. Low-risk or fully determined steps can bypass the model; harder turns receive bounded serial planning, execution, and one malformed-output retry. The frozen full public run reports 36.0% Pass3 and 54.7% Pass@3 over 375 episodes, with an audited maximum depth of three and no steps above five. A staged 36-task development program improved Pass3 while reducing depth, but public results reveal weak handling of missing parameters, missing response fields, and internal evidence. The report also notes a large train-to-public gap and long failed loops requiring progress detection."},"metrics":{"pass3":0.166666666667,"passAt3":0.233333333333,"pass1":0.2,"categories":{"base":{"pass3":0.1,"pass_at_3":0.1,"pass1":0.1},"hallucination":{"pass3":0.3,"pass_at_3":0.4,"pass1":0.4},"disambiguation":{"pass3":0.1,"pass_at_3":0.2,"pass1":0.1}},"successfulTrials":17,"successfulTrialsTotal":90,"successConsistency":0.714285714286,"taskLatencyMeanMs":5137.511111111111,"taskLatencyMedianMs":4190.65,"taskLatencyP95Ms":13768.9,"turnLatencyMedianMs":531.85,"meanTokensPerTrial":106062.60377358491,"estimatedCostPerTrialUsd":0.051105533962,"rank":{"start":9,"end":10,"total":13,"label":"9.-10./13"}}},{"key":"track_2__team-3","track":"track_2","teamId":"team-3","teamName":"yeboi","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-3.pdf","award":null,"summary":{"punchline":"Parallel voted verifier gates manufacture cautious dissent absent from the executor, forcing preference gathering or abstention while keeping sequential depth to three calls.","body":"Yeboi runs a gpt-oss-120b executor alongside voted grounding, ambiguity, and policy gates in one parallel burst. A deterministic asymmetric aggregator prioritizes missing-capability abstention, then a disambiguation ladder that checks policy, explicit instructions, preferences, defaults, and context before asking the user; only vetoes open one repair-and-reverify loop. Gate-specific reasoning effort and greedy executor decoding keep the deepest sequential path at three calls. On the public test split, the report gives macro Pass3 0.413 versus 0.27 for a raw single-pass baseline, with median decision latency around 2.5 seconds. Matched ablations attribute genuine new behavior only to the ambiguity gate: grounding did not generalize, the policy gate hurt Base, and an over-action rule was reverted. The baseline and submitted scores use different public task sets, so their comparison is not fully matched; small disambiguation slices also varied substantially."},"metrics":{"pass3":0.166666666667,"passAt3":0.4,"pass1":0.266666666667,"categories":{"base":{"pass3":0.2,"pass_at_3":0.3,"pass1":0.2},"hallucination":{"pass3":0.3,"pass_at_3":0.6,"pass1":0.4},"disambiguation":{"pass3":0.0,"pass_at_3":0.3,"pass1":0.2}},"successfulTrials":25,"successfulTrialsTotal":90,"successConsistency":0.541666666667,"taskLatencyMeanMs":11419.467777777778,"taskLatencyMedianMs":9880.35,"taskLatencyP95Ms":24584.3,"turnLatencyMedianMs":1220.75,"meanTokensPerTrial":361922.6842105263,"estimatedCostPerTrialUsd":0.168788711842,"rank":{"start":9,"end":10,"total":13,"label":"9.-10./13"}}},{"key":"track_2__team-20","track":"track_2","teamId":"team-20","teamName":"BigDog","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-20.pdf","award":null,"summary":{"punchline":"PACT compiles model proposals into contract-bound PlanIR certificates whose deterministic runtime carries successful action evidence across replanning horizons.","body":"PACT limits the model to proposing a bounded PlanIR graph over Observe, Ask, Confirm, Act, and Respond nodes. Deterministic code strictly decodes that graph, validates full live JSON schemas and capability digests, rechecks arguments before emission, scopes confirmations to operation and arguments, and requires every reported-success Act key to remain closure evidence after replanning. Semantic data starts a new verified horizon, while exact confirmations and matched status-only Act results advance the immutable suffix without another model call. A horizon uses one proposal, at most one repair, and an action-plan audit, for a maximum depth of three. The release passed 356 tests plus three subtests and protocol smoke checks, but reports no public aggregate. Language meaning, truthful effect metadata, intended consent, and cryptographic event correlation remain outside its guarantees."},"metrics":{"pass3":0.133333333333,"passAt3":0.3,"pass1":0.233333333333,"categories":{"base":{"pass3":0.0,"pass_at_3":0.1,"pass1":0.0},"hallucination":{"pass3":0.4,"pass_at_3":0.7,"pass1":0.6},"disambiguation":{"pass3":0.0,"pass_at_3":0.1,"pass1":0.1}},"successfulTrials":18,"successfulTrialsTotal":90,"successConsistency":0.5,"taskLatencyMeanMs":21628.91888888889,"taskLatencyMedianMs":17087.800000000003,"taskLatencyP95Ms":49957.8,"turnLatencyMedianMs":2726.5,"meanTokensPerTrial":191617.33720930232,"estimatedCostPerTrialUsd":0.079668418023,"rank":{"start":11,"end":12,"total":13,"label":"11.-12./13"}}},{"key":"track_2__team-17","track":"track_2","teamId":"team-17","teamName":"Icthej","mainLlm":"Cerebras gpt-oss-120b","report":"reports/track_2/team-17.pdf","award":null,"summary":{"punchline":"EpiSCo-Guard scopes completion evidence by request, arguments, and source before selecting adaptive parallel Cerebras rollouts through deterministic consensus.","body":"EpiSCo-Guard maintains an append-only evidence ledger that binds tool results to pending calls, turn time, source, and critical arguments, preventing stale successes from proving a new request. Deterministic fast paths handle grounded actions, ambiguity, and unavailable capabilities; otherwise a risk gate launches two, four, or eight independent Cerebras candidates. A hard verifier rejects malformed, schema-invalid, unsupported, or unsafe actions, then canonical action-signature voting selects among valid candidates. The report records 129/129 on a one-trial public-train run and an improvement from 1/5 to 5/5 on targeted tasks, plus two repaired blind stale-evidence cases. It explicitly cautions that this does not establish hidden Pass3, and that new schemas, unusual paraphrases, and interacting policy obligations remain possible failure sources."},"metrics":{"pass3":0.133333333333,"passAt3":0.166666666667,"pass1":0.133333333333,"categories":{"base":{"pass3":0.2,"pass_at_3":0.2,"pass1":0.2},"hallucination":{"pass3":0.2,"pass_at_3":0.3,"pass1":0.2},"disambiguation":{"pass3":0.0,"pass_at_3":0.0,"pass1":0.0}},"successfulTrials":14,"successfulTrialsTotal":90,"successConsistency":0.9,"taskLatencyMeanMs":140.72222222222223,"taskLatencyMedianMs":122.55000000000001,"taskLatencyP95Ms":264.8,"turnLatencyMedianMs":16.4,"meanTokensPerTrial":null,"estimatedCostPerTrialUsd":null,"rank":{"start":11,"end":12,"total":13,"label":"11.-12./13"}}},{"key":"track_2__team-19","track":"track_2","teamId":"team-19","teamName":"Nahed Innovation","mainLlm":"autex-carbench-agent","report":"reports/track_2/team-19.pdf","award":null,"summary":{"punchline":"Autex puts a zero-call reliability kernel and deterministic vehicle-health scorer ahead of one temperature-zero LLM verifier.","body":"Autex first applies deterministic guards for missing tools, unsupported parameters, incomplete results, domain policies, and ambiguity resolution. Its Morphological Predictive Allocation Engine then scores telemetry with forward-risk, stability, and context-weighted objectives to select monitor, stabilize, service-soon, or stop-and-inspect; only the second stage invokes a configurable LLM verifier. The report summarizes 369 CAR-bench trials across four frontier models and identifies missing response fields as the persistent hallucination weakness, while schema-visible missing parameters fare much better. MPAE is reported to produce no false escalations on 541 sampled OBD-II records, and a critical-context override fixed two stress cases. The main caveat is that runtime result-completeness still depends on consistent model recognition, while temperature zero reduces but does not eliminate variance."},"metrics":{"pass3":0.033333333333,"passAt3":0.033333333333,"pass1":0.033333333333,"categories":{"base":{"pass3":0.0,"pass_at_3":0.0,"pass1":0.0},"hallucination":{"pass3":0.1,"pass_at_3":0.1,"pass1":0.1},"disambiguation":{"pass3":0.0,"pass_at_3":0.0,"pass1":0.0}},"successfulTrials":3,"successfulTrialsTotal":90,"successConsistency":1.0,"taskLatencyMeanMs":4992.966666666666,"taskLatencyMedianMs":4567.0,"taskLatencyP95Ms":7095.6,"turnLatencyMedianMs":523.5,"meanTokensPerTrial":183335.55555555556,"estimatedCostPerTrialUsd":null,"rank":{"start":13,"end":13,"total":13,"label":"13./13"}}}]};
